def __find_main_window() -> bool:
    """Searches for the main window of the D and I UI. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the d_and_i.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(DandI.Main_Window) is not None else False


def __find_promote_plan_dialog() -> opt[object]:
    """Searches for the Promote Plan dialog window within the D and I workflow. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the d_and_i.py file context!

    :return: Found object or None
    :rtype: object
    """
    return CommonActions.find_object(DandI.promotePlan_Main_Dialog) #is not None else False

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def clear_text_box(textboxObject: dict) -> None:
    """Clicks a give textboxObject > inputs the Shift+Ctrl+a keyboard sequence (this is Mosaiq specific to highlight all the text in the textbox) >
    inputs a delete key press

    :param textboxObject: Object Map of the target textbox
    :type textboxObject: dict
    """
    CommonActions.left_click_object(textboxObject)
    CommonActions.press_key_sequence("<Shift+Ctrl+a>")
    CommonActions.press_delete_key()

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_close_d_and_i() -> None:
    """Locates the D and I main window > then clicks the Close button.
    """
    if __find_main_window():
        CommonActions.left_click_object(DandI.Close_Button)
        #if CommonActions.wait_for_object_to_disappear(DandI.Main_Window) is False:
        # Note: Check for D and I window sometimes incorrectly returns False when closed.
        # Check the Close button in the D and I window is not available instead
        if CommonActions.wait_for_object_to_disappear(DandI.Close_Button) is False:
            # Try again
            CommonActions.left_click_object(DandI.Close_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def open_diagnoses_and_problems_window(waitTimeout: int = 30000) -> bool:
    """Locates the main D and I UI window > clicks the Diagnosis button > Waits for the Diagnoses and Problems List window to appear

    # NOTE: Although the Diagnoses and Problems List window may appear soon after clicking the Diagnosis button, it can take at
    least 30 seconds (or more) for Squish to recognise it as an active (ready state) window. This waitTimeout should be
    extended for slow performing Mosaiq machines.

    :param int waitTimeout: The timeout in milliseconds to wait for the Diagnoses and Problems window to appear
    :return: True if the Diagnoses and Problems window is opened, False otherwise
    """
    if __find_main_window():
        CommonActions.left_click_object(DandI.Diagnosis_Button)
        return True if CommonActions.find_object(DandI.diagnoses_and_problems_Window, timeout=waitTimeout) is not None else False
    return False

