@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_d_and_i_promote_button(waitForPromotePlanDialog: bool = True) -> None:
    """Locates the main D and I UI window > clicks the Promote button > then waits for the Promote Plan dialog to appear.

    :param bool waitForPromotePlanDialog: If True, waits for the subsequent Promote Plan dialog to appear
    """
    if __find_main_window():
        CommonActions.find_object(DandI.Promote_Button, 30000)
        CommonActions.left_click_object(DandI.Promote_Button)
        if waitForPromotePlanDialog:
            try:
                CommonActions.find_object(DandI.promotePlan_Main_Dialog)
            except FailedToFindObject:
                # Sometimes the promote button is not selected on the first attempt. Try again if it fails to open the plan promotion dialog.
                CommonActions.left_click_object(DandI.Promote_Button)
                CommonActions.find_object(DandI.promotePlan_Main_Dialog)

