@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_treatment_promote_button(waitTimeout: int = 30) -> bool:
    """Locates the D and I - Promote Plan dialog UI object > then clicks the Promote button and waits for the dialog to disappear.
    :param waitTimeout: Time in seconds to wait for the Promote Treatment Plan dialog to disappear if the plan has been promoted successfully.
    :return bool: True if the Promote Treatment Plan dialog has disappeared, False otherwise
    """
    dialog =  __find_promote_plan_dialog()
    if dialog:
        #Maximize the 'Promote Treatment Plan' dialog by shortcut of input of "X" to the right mouse popup menu in case part of it being hidden
        CommonActions.mouse_click(dialog, 10, 10, False)
        CommonActions.native_text_type("X")
        
        CommonActions.find_object(DandI.promotePlan_Promote_Button, 40000)
        CommonActions.left_click_object(DandI.promotePlan_Promote_Button)
        if CommonActions.wait_for_object_to_disappear(DandI.promotePlan_Main_Dialog, timeoutInSecs=waitTimeout) is False:
            # Try pressing the Promote button again as it sometimes fails to get selected on first attempt
            CommonActions.left_click_object(DandI.promotePlan_Promote_Button)
            return CommonActions.wait_for_object_to_disappear(DandI.promotePlan_Main_Dialog, timeoutInSecs=waitTimeout)
        return True
    return False

