@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_specified_item_in_list_view(itemSearchString: str, setDefaultSelectionToStart: bool = True, handleOcrAnomalies: bool = False) -> bool:
    """Locates the main D and I UI window > scans the main list view for the specified item text string > clicks the screen area it is located.

    :param str itemSearchString: The text string to be searched in the D and I list view
    :param bool setDefaultSelectionToStart: If True, sets the default selection to the first item in the list
    :param bool handleOcrAnomalies: If True, handles OCR anomalies by adding various permutations of special characters to the search string
    :return bool: True if the item was found and clicked, False otherwise
    """
    if __find_main_window():
        if setDefaultSelectionToStart:
            CommonActions.press_home_key()
        item_object = None
        for searchObj in [DandI.Main_View_List, DandI.Main_Window]:
            textFound = CommonActions.get_all_text_via_ocr_in_object(searchObj)
            if itemSearchString in textFound:
                print(f"Found in:\n{textFound}")
                # Searching text by OCR often results in anomalies such as icons or vertical lines getting misidentified as certain characters.
                # Extra logic used to factor in these misidentified characters by adding numerous permutations of these to the search string
                if handleOcrAnomalies:     
                    item_object = __find_obj_by_ocr_with_special_characters_prefix(searchText=itemSearchString, searchObject=searchObj, matchingText=textFound)              
                else: 
                    item_object = CommonActions.get_object_by_ocr_text_in_object(searchObj, itemSearchString)
                if item_object is not None:
                    CommonActions.click_screen_area_object(item_object)
                    return True
            else:
                print(f"Not in:\n{textFound}")
    return False

