@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def choose_machine_from_plan(machineName: str, locationDirRetries: int = 4) -> None:
    """Selects a given machineName from the Location Directory window and left clicks it.

    :param str machineName: machine name to choose from location_Directory view
    :param int locationDirRetries: Number of retries to scroll down the location directory
                                   list until the specific machine name is found
    """
    try:
        # Press the Home button to move current selection to start
        CommonActions.press_home_key()
        machineNameObject = CommonActions.get_object_by_ocr_text_in_object(DandI.location_Directory_RO_Window, machineName, 10000)
        CommonActions.click_screen_area_object(machineNameObject)
    except SyntaxError:
        # Try scrolling down the page by pressing Pg Down keyboard button several times
        for i in range(locationDirRetries):
            try:
                CommonActions.press_page_down_key()
                machineNameObject = CommonActions.get_object_by_ocr_text_in_object(DandI.location_Directory_RO_Window, machineName, 10000)
                CommonActions.click_screen_area_object(machineNameObject)
                break
            except SyntaxError:
                pass

