def __find_obj_by_ocr_with_special_characters_prefix(searchText: str, searchObject: dict, matchingText: str="", timeout: int = 3000) -> opt[object]:
    """Helper function to add a special character that is typically added to the start of a text string
    found when using OCR (e.g. unpromoted and promoted plans) in the D and I list view.
    Tries first in the matching text to match, and then find the combination of the searched text string with several variations of prefixed special 
    characters(in the filetered list as a result of matching), where vertical table lines and icons are misidentified by OCR as a number of different 
    characters.

    Returns the object using OCR if the searchText is found in the search object(e.g., D&I window, or D&I list view)

    -> Hidden function that should not be used outside the context of the d_and_i.py file context!

    :params: str searchText: Text string to search for in the Diagnoses and Interventions window
             dict searchObject: the search area that has the searchText
             str matchingText: the OCR text that contains the varied form of the searchText
             int timeout: the timeout for get_object_by_ocr_text_in_object function
    :return: Found object or None if not found
    :rtype: object
    """

    # Note: OCR sometimes misidentifies the icons as some obscure characters next to the text found in the D and I list
    possible_prefix_list = ["", "-4f)", "-Â¢f1", "LÂ¢fl", "L4\\", "LÂ¢i", "L4Ji", "4/1", "4", "4l", "Â¢#1", "Â¢41", "4Â¢", "@", "1", "Â¢1", "</1", "f1", "Â¢/1", "Â¢/", "Â¢f1", "L4gi", "4@i", "-4@i"]
    search_area_obj = searchObject
    filtered_prefix_list = []
    if matchingText:
        #prioritize the prefixed text in the matching text
        for line in matchingText.split("\n"):
            if searchText in line:
                filtered_prefix_list.append(line[:-len(searchText)])
    
        for prefix in possible_prefix_list:
            if (prefix+searchText) in matchingText:
                filtered_prefix_list.append(prefix)

    else:
        filtered_prefix_list = possible_prefix_list

    for prefix in filtered_prefix_list:
        # Try prefixing a common character to the searched text string
        found_session_obj = CommonActions.get_object_by_ocr_text_in_object(search_area_obj, prefix + searchText, timeout)
        if found_session_obj is not None:
            #print(f"Searching text:{searchText},  Matched OCR text:{prefix + searchText}")
            logger.info(f"Found object with OCR text prefxed with '{prefix}': {searchText}")
            return found_session_obj
    return None


