@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def read_pat_id_from_service_info_window() -> opt[str]:
    """Return the Pat_ID1 value from the Service Info - Tx field window

    :return: The Pat_ID1 string value if found, None otherwise
    """
    if CommonActions.find_object(DandI.service_Info_Tx_Field_Window) is not None:
        service_info_string = CommonActions.get_uneditable_field_objects_text_value(DandI.service_Info_Label)
        # extract the Pat_ID1 value from the string
        service_info_list = service_info_string.split()
        if service_info_list is not None:
            # PAT ID value is next to the "Pat_ID1" label (typically second item in the list)
            return service_info_list[service_info_list.index("Pat_ID1") + 1]
